mapper.select:
select 
from spot_reservation_rule
where 1 = 1

    and scenic_area_id = #{scenicAreaId}


    and spot_id = #{spotId}


    and status = #{status}

order by id desc

select r.id, r.scenic_area_id, r.spot_id, r.start_time, r.end_time, r.total_capacity, r.week_days, r.advance_days, r.status, r.remark, r.create_by, r.create_time, r.update_by, r.update_time from spot_reservation_rule r inner join scenic_spot s on s.id = r.spot_id where r.status = 1 and s.status = 1 and s.deleted = 0 and s.reservation_enabled = 1
and r.scenic_area_id = #{scenicAreaId}
and r.spot_id = #{spotId}
order by r.spot_id asc, r.start_time asc

mapper.insert:
insert into spot_reservation_rule (
    scenic_area_id, spot_id, start_time, end_time, total_capacity, week_days,
    advance_days, status, remark, create_by, create_time, update_by, update_time
) values (
    #{scenicAreaId}, #{spotId}, #{startTime}, #{endTime}, #{totalCapacity}, #{weekDays},
    #{advanceDays}, #{status}, #{remark}, #{createBy}, #{createTime}, #{updateBy}, #{updateTime}
)

mapper.update:
update spot_reservation_rule
start_time = #{startTime}, end_time = #{endTime}, total_capacity = #{totalCapacity}, week_days = #{weekDays}, advance_days = #{advanceDays}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where id = #{id}
